css:
:scope { width: min(100%, 1086px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 8; font-family: var(--os-font-heading); font-size: 59.2px; font-weight: 380; line-height: 1.08; letter-spacing: -0.015em; color: var(--os-color-text); }
.gx__i2 { grid-column: 1 / span 12; grid-row: 12 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i3 { grid-column: 13 / span 12; grid-row: 12 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 12; grid-row: 17 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i5 { grid-column: 13 / span 12; grid-row: 17 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i6 { grid-column: 1 / span 12; grid-row: 21 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
