.gx__i9 { grid-column: 13 / span 12; grid-row: 25 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i10 { grid-column: 1 / span 12; grid-row: 30 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i11 { grid-column: 13 / span 12; grid-row: 30 / span 4; font-family: var(--os-font-label); font-size: 18px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: var(--os-color-text); }
